import csv, collections, re

with open('workspace/data/test_center_logs.csv', newline='', encoding='utf-8') as f:
    rows = list(csv.DictReader(f))

texts = [r['raw_reason_text'] for r in rows]

# Collect all distinct "tokens" separated by common delimiters: , / + ; space CJK
# First, let's see what kinds of whitespace and delimiters exist
delims = collections.Counter()
for t in texts:
    for ch in t:
        if ch in ' ,;/+&，、；;：:\u3000':
            delims[ch]+=1
print("delimiter char counts:", dict(delims))

# Split each text on delimiters into candidate atoms, strip, drop empties
atom_counter = collections.Counter()
for t in texts:
    # split on these
    parts = re.split(r'[,，/;；、+&\s]+', t)
    for p in parts:
        p = p.strip()
        if p:
            atom_counter[p]+=1

print("\ntotal distinct atoms (after split):", len(atom_counter))
print("\n--- all atoms with count >= 5 ---")
for a,c in atom_counter.most_common():
    if c>=5:
        print(f"{c:6d} | {a}")

